\begin{tikzpicture}[x=1.55cm,y=0.52cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-2.4,-1) rectangle (4.8,8.5);
\draw[black,line width=0.5pt,->] (-2.2,0)--(1.9,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-0.5)--(0,7.8) node[above] {$y$};
\foreach \v in {1,2,3,6}{\draw[black,line width=0.4pt] (-0.05,\v)--(0.05,\v);\node[left] at (-0.05,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\draw[black,line width=0.4pt] (1,-0.12)--(1,0.12);
\node[below] at (1,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$1$\special{dvisvgm:raw </g>}};
\draw[black,line width=0.8pt,->] plot[domain=-2:1.8,samples=100] (\x,{pow(3,\x)});
\draw[black,line width=0.8pt,dashed,->] plot[domain=-2:1.2,samples=100] (\x,{2*pow(3,\x)});
\draw[black,line width=0.8pt,densely dotted,->] plot[domain=-2:0.9,samples=100] (\x,{pow(3,2*\x)});
\draw[black,line width=0.8pt] (2.2,6.8)--(2.6,6.8) node[right] {$y=3^x$};
\draw[black,line width=0.8pt,dashed] (2.2,5.3)--(2.6,5.3) node[right] {$y=2\times3^x$};
\draw[black,line width=0.8pt,densely dotted] (2.2,3.8)--(2.6,3.8) node[right] {$y=3^{2x}$};
\end{tikzpicture}

