\draw[black,line width=0.5pt,->] (-0.5,0)--(5.6,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-3)--(0,3.7) node[above] {$y$};
\foreach \v in {1,2,3}{\draw[black,line width=0.4pt] (\v,-0.06)--(\v,0.06);\node[below] at (\v,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\foreach \v in {-2,-1,1,2}{\draw[black,line width=0.4pt] (-0.06,\v)--(0.06,\v);\node[left] at (0,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
